double ft = 0.3048;
string name = Tama.Args.Get(args, "locationName", "");
double ew = Tama.Args.Get(args, "ew", 0.0), ns = Tama.Args.Get(args, "ns", 0.0), el = Tama.Args.Get(args, "elevation", 0.0), ang = Tama.Args.Get(args, "angleDeg", 0.0);

ProjectLocation target = null;
foreach (ProjectLocation pl in doc.ProjectLocations) if (pl.Name == name) target = pl;
if (target == null) throw new Exception("Location not found: " + name);
if (target.Id == doc.ActiveProjectLocation.Id) throw new Exception("Target is the current site - refused.");
if (WorksharingUtils.GetCheckoutStatus(doc, target.Id) == CheckoutStatus.OwnedByOtherUser) throw new Exception("Site owned by another user.");

var act = doc.ActiveProjectLocation;
var actBefore = act.GetProjectPosition(XYZ.Zero);
var sp = new FilteredElementCollector(doc).OfClass(typeof(BasePoint)).Cast<BasePoint>().First(b => b.IsShared);
var spBefore = sp.SharedPosition;
var oldPos = target.GetProjectPosition(XYZ.Zero);

var pp = target.GetProjectPosition(XYZ.Zero);
pp.EastWest = ew / ft; pp.NorthSouth = ns / ft; pp.Elevation = el / ft; pp.Angle = ang * Math.PI / 180;
target.SetProjectPosition(XYZ.Zero, pp);
doc.Regenerate();

var a2 = act.GetProjectPosition(XYZ.Zero);
if (Math.Abs(a2.EastWest-actBefore.EastWest)+Math.Abs(a2.NorthSouth-actBefore.NorthSouth)+Math.Abs(a2.Elevation-actBefore.Elevation) > 0.003 || Math.Abs(a2.Angle-actBefore.Angle) > 1e-8)
  throw new Exception("Current site changed - rolled back.");
if (sp.SharedPosition.DistanceTo(spBefore) > 0.003) throw new Exception("Survey point changed - rolled back.");

var n = target.GetProjectPosition(XYZ.Zero);
Func<ProjectPosition, object> f = p => new { ew = Math.Round(p.EastWest*ft,4), ns = Math.Round(p.NorthSouth*ft,4), elev = Math.Round(p.Elevation*ft,4), angle = Math.Round(p.Angle*180/Math.PI,6) };
return new { site = target.Name, before = f(oldPos), after = f(n), currentSite = act.Name, currentUnchanged = f(a2) };
